window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[52]={"id":"052","numero":52,"titre":"Strabisme et amblyopie de l'enfant","objectifs":[{"id":"52-1","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les étapes de mise en place de la vision binoculaire chez l’enfant","contenu":"<p>La <span class=\"kw-def\">vision binoculaire</span> résulte d’une <strong>maturation corticale active</strong> dans une fenêtre développementale étroite : tout obstacle à la formation d’images nettes et alignées pendant cette période peut interrompre définitivement le programme.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Composantes de la vision binoculaire</h4>\n      <table >\n        <thead><tr><th>Composante</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Fusion</span></strong></td>\n            <td>Intégration corticale qui réunit <span class=\"kw-clinique\">les</span> images perçues par chaque œil en <strong>une image unique</strong>. Se traduit par une réponse motrice (contraction-relâchement des muscles oculomoteurs) à des stimulations binoculaires → permet in fine la <strong>stéréoscopie</strong> (vision fine du relief).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Correspondance rétinienne</span></strong></td>\n            <td>Liaison corticale entre <span class=\"kw-clinique\">les</span> neurones provenant des <strong>2 fovéas</strong> (et 2 à 2 entre les neurones provenant des zones normalement correspondantes des 2 rétines).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Vision stéréoscopique</span></strong></td>\n            <td>Perception fine du relief, étage le plus élaboré de la vision binoculaire. Évaluée par <span class=\"kw-clinique\">les</span> stéréotests (Lang, Randot, Wirt, TNO).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Chronologie développementale ⭐</h4>\n      <ul>\n        <li><strong>Période sensible</strong> du développement de la vision binoculaire = <span class=\"kw-chiffre\">avant 6 à 9 mois</span> de vie.</li>\n        <li>Si <span class=\"kw-clinique\">les</span> axes visuels <strong>ne sont pas alignés</strong> pendant cette fenêtre (strabisme précoce), la correspondance rétinienne normale <strong>ne peut pas se faire</strong>.</li>\n        <li>Conséquence : <span class=\"kw-alerte\">absence définitive de vision stéréoscopique fine</span> — aucune intervention ultérieure ne pourra restaurer une organisation corticale normale.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Mécanismes de défense corticale en cas de strabisme</h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Conséquence corticale</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Strabisme aigu</strong> (<span class=\"kw-etio\">acquis</span> tardivement)</td>\n            <td>\n              <span class=\"kw-clinique\">Diplopie binoculaire</span> (2 images d’un même objet)<br>\n              <span class=\"kw-clinique\">Confusion visuelle</span> (<span class=\"kw-clinique\">les</span> images de 2 objets distincts se superposent)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Strabisme ancien</strong> ou jeune enfant — <em>neutralisation</em></td>\n            <td>\n              <strong>&gt; <span class=\"kw-chiffre\">8-10 ans</span> :</strong> la neutralisation permet d’éviter la diplopie<br>\n              <strong>&lt; <span class=\"kw-chiffre\">8-10 ans</span> :</strong> si la neutralisation s’effectue constamment aux dépens du même œil → <span class=\"kw-alerte\">amblyopie</span> (à prévenir et traiter)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Strabisme précoce</strong> (&lt; <span class=\"kw-chiffre\">6-9 mois</span>)</td>\n            <td><span class=\"kw-alerte\">Absence définitive de vision stéréoscopique fine</span> — la correspondance rétinienne ne s’établit pas.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Implication clinique.</strong> Plus l’apparition du strabisme est <em>précoce</em>, moins le développement d’une vision binoculaire normale est probable. À l’inverse, la fin du développement visuel se situe autour de <span class=\"kw-chiffre\">8-10 ans</span> : au-delà de cet âge, toute amblyopie est considérée comme <span class=\"kw-alerte\">définitive</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> médical du nourrisson, de l’enfant et de l’adolescent · 55 — Développement psychomoteur du nourrisson</em></p>","frequence":0},{"id":"52-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de dépistage d’un strabisme et d’un risque d’amblyopie chez l’enfant","contenu":"<p>Le <span class=\"kw-def\">dépistage</span> est <strong>fondamental</strong> car la fenêtre thérapeutique est étroite : une PEC avant <span class=\"kw-chiffre\">2 ans</span> aboutit à un succès dans <span class=\"kw-chiffre\">&gt; 90 %</span> des cas, alors que <span class=\"kw-clinique\">les</span> espoirs de récupération sont <span class=\"kw-alerte\">très faibles après 8 ans</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Définitions à connaître ⭐</h4>\n      <ul>\n        <li><span class=\"kw-def\">Strabisme</span> : trouble <strong>oculomoteur</strong> caractérisé par une <span class=\"kw-def\">déviation des axes visuels</span>. Comporte toujours une <strong>composante motrice</strong> et une <strong>composante sensorielle</strong>.</li>\n        <li><span class=\"kw-def\">Amblyopie</span> (sens strict, fonctionnelle) : acuité visuelle effective d’un œil <strong>inférieure</strong> à l’acuité visuelle optimale théorique → différence <span class=\"kw-chiffre\">≥ 2/10ᵉ</span> entre <span class=\"kw-clinique\">les</span> 2 yeux avec correction.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Quand un strabisme est-il pathologique ? ⭐</h4>\n      <table >\n        <thead><tr><th>Caractère</th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Strabisme intermittent et alternant <span class=\"kw-chiffre\">avant 3 mois</span></strong></td>\n            <td>Peut être <span class=\"kw-chiffre\">non pathologique</span> — simple retard d’acquisition de l’oculomotricité avec spasmes accommodatifs.</td>\n          </tr>\n          <tr>\n            <td><strong>Strabisme <span class=\"kw-alerte\">constant</span></strong></td>\n            <td>Toujours pathologique, quel que soit l’âge.</td>\n          </tr>\n          <tr>\n            <td><strong>Strabisme <span class=\"kw-alerte\">divergent / exotropie</span></strong></td>\n            <td>Toujours pathologique. Si précoce (&lt;<span class=\"kw-chiffre\"> 9 mois</span>) → souvent associé à des <span class=\"kw-alerte\">anomalies cérébrales</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Strabisme <span class=\"kw-alerte\">après 3 mois</span></strong></td>\n            <td>Toujours pathologique → exploration ophtalmologique requise.</td>\n          </tr>\n          <tr>\n            <td><strong>CAT</strong></td>\n            <td>Tout strabisme doit être considéré comme une <span class=\"kw-alerte\">urgence</span> → vu initialement dans un délai de <span class=\"kw-chiffre\">1 semaine</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Dépistage</span> de l’amblyopie — par âge ⭐</h4>\n      <table >\n        <thead><tr><th>Âge</th><th>Méthode</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Âge pré-verbal — évaluation comportementale</strong></td>\n            <td>\n              Poursuite-fixation, sourires-réponses, défense à l’occlusion, harmonie marche/jeu<br>\n              <strong>Bébé vision / test de Teller</strong> : technique du regard préférentiel, approche l’AV dès <span class=\"kw-chiffre\">4-6 mois</span> (non quantitatif, chronophage → peu utilisé en <span class=\"kw-def\">dépistage</span> de <span class=\"kw-clinique\">masse</span>)<br>\n              <strong>Test d’occlusion</strong> : patch alterné → <span class=\"kw-alerte\">réaction de défense lors de l’occlusion de l’œil sain</span> = évocateur d’amblyopie<br>\n              <strong>Test stéréoscopique</strong> (Lang) : entre <span class=\"kw-chiffre\">9 et 15 mois</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Âge verbal</strong></td>\n            <td>\n              <strong><span class=\"kw-chiffre\">2,5 - 4 ans</span> :</strong> tests de P<span class=\"kw-chiffre\">iga</span>ssou, du Cadet<br>\n              <strong><span class=\"kw-chiffre\">≥ 5 ans</span> :</strong> tests du Cadet, échelle de Monoyer<br>\n              ⚠️ Le <span class=\"kw-def\">dépistage</span> repose <em>moins sur le <span class=\"kw-def\">score</span> brut</em> que sur la <span class=\"kw-alerte\">différence entre les 2 yeux (≥ 2/10ᵉ → suspecter amblyopie)</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Diagnostic positif</span> d’un strabisme au cabinet ⭐</h4>\n      <ul>\n        <li><strong>Étude des reflets cornéens</strong> : reflet <em>dévié</em> pour l’œil strabique (par rapport au reflet centré sur l’œil fixateur).</li>\n        <li><strong>Test à l’écran unilatéral alterné</strong> : recherche d’un <span class=\"kw-clinique\">mouvement de refixation</span> de l’œil strabique lors de la levée d’occlusion.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Réfraction objective sous cycloplégique.</strong> Pratiquée chez <em>tout enfant entre 9 et <span class=\"kw-chiffre\">12 mois</span></em> : mesure l’amétropie sans accommodation (myopie, hypermétropie, ast<span class=\"kw-chiffre\">igm</span>atisme) <strong>+ fond d’œil dans le même temps</strong>. Cycloplégiant : <span class=\"kw-ttt\">atropine</span> chez le petit enfant (plusieurs jours avant), <span class=\"kw-ttt\">cyclopentolate</span> chez l’enfant plus grand (<span class=\"kw-chiffre\">45 min</span> avant). <span class=\"kw-alerte\">🚩 Risque fort de strabisme/amblyopie</span> si <strong>hypermétropie &gt; 3,5 D</strong>, <strong>astigmatisme &gt; 1,5 D</strong>, ou <strong>anisométropie &gt; 1 D</strong>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> nourrisson, enfant, adolescent · 55 — Développement psychomoteur</em></p>","frequence":1},{"id":"52-3","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principes d’examen pour une suspicion de strabisme chez un enfant","contenu":"<p>Le bilan d’un strabisme se structure en <strong>4 axes complémentaires</strong>. Ils visent à <em>caractériser</em> le strabisme, à <em>identifier sa cause</em> (paralytique <span class=\"kw-bio\">vs</span> sensoriel <span class=\"kw-bio\">vs</span> maladie), et à <em>poser le <span class=\"kw-def\">pronostic</span></em> et l’indication thérapeutique.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Axe 1 — Examen de la motilité oculaire</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Objectif</strong></td>\n            <td>Diagnostiquer un strabisme-symptôme d’une <span class=\"kw-alerte\">paralysie oculomotrice</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Ductions</strong></td>\n            <td>Mouvements effectués par <em>1 seul œil</em> (l’autre étant caché).</td>\n          </tr>\n          <tr>\n            <td><strong>Versions</strong></td>\n            <td>Mouvements <em>conjugués</em> des 2 yeux dans la même direction.</td>\n          </tr>\n          <tr>\n            <td><strong>Strabismes concomitants</strong></td>\n            <td>Grande majorité des strabismes de l’enfant — pas de déficit systématisé de la motilité.</td>\n          </tr>\n          <tr>\n            <td><strong>Strabismes incomitants</strong></td>\n            <td>Présumés paralytiques. L’angle entre <span class=\"kw-clinique\">les</span> 2 yeux varie dans l’espace. Exemple : <em>paralysie du VI droit</em> → limitation de l’abduction de l’œil droit, angle ↑↑ dans le regard à droite, angle normal/réduit dans le regard à gauche.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Axe 2 — Réfraction objective sous cycloplégique ⭐</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Principe</strong></td>\n            <td>Mesure de la puissance réfractive après instillation d’un collyre cycloplégiant (paralysie de l’accommodation) :<br>\n              <strong>Petit enfant :</strong> <span class=\"kw-ttt\">atropine</span> plusieurs jours avant<br>\n              <strong>Enfant plus grand :</strong> <span class=\"kw-ttt\">cyclopentolate</span><span class=\"kw-chiffre\"> 45 min</span> avant\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Pourquoi ?</strong></td>\n            <td><span class=\"kw-clinique\">Les</span> capacités d’accommodation sont très importantes chez l’enfant → une mesure correcte de la réfraction nécessite une <strong>cycloplégie</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Objectif</strong></td>\n            <td>Rechercher <span class=\"kw-clinique\">les</span> amétropies à fort risque d’amblyopie/strabisme :<br>\n              <span class=\"kw-alerte\">Hypermétropie &gt; 3,5 D</span><br>\n              <span class=\"kw-alerte\">Astigmatisme &gt; 1,5 D</span><br>\n              <span class=\"kw-alerte\">Anisométropie &gt; 1 D</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Lien hypermétropie-strabisme</strong></td>\n            <td>Hypermétropie très fréquemment associée au strabisme : effort d’accommodation excessif → syncinésie accommodation-convergence-myosis → convergence excessive → strabisme.</td>\n          </tr>\n          <tr>\n            <td><strong>Autre utilité</strong></td>\n            <td>Préalable à toute mesure de l’AV avec correction → tout enfant strabique doit porter la <strong><span class=\"kw-ttt\">correction optique totale</span></strong>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Axe 3 — Mesure de la déviation et tests de vision binoculaire</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Principe et interprétation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Mesure de l’angle de déviation</strong></td>\n            <td>Réalisée à l’examen sous écran avec interposition de <strong>prismes</strong>, sans puis avec correction optique.</td>\n          </tr>\n          <tr>\n            <td><strong>Test à l’écran unilatéral</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Tropie</span> (strabisme patent) : déviation présente à l’écran unilatéral<br>\n              <span class=\"kw-clinique\">Phorie</span> (strabisme latent) : déviation présente uniquement à l’écran alterné\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Test à l’écran alterné</strong></td>\n            <td>Cherche un mouvement de <strong>restitution</strong> (passage d’une position déviée à une position de fixation) lors de la levée d’occlusion → évoque un strabisme.</td>\n          </tr>\n          <tr>\n            <td><strong>Stéréotests</strong> (Lang, Randot, Wirt, TNO)</td>\n            <td>\n              Quantifient la <strong>vision binoculaire</strong><br>\n              Déficit = vision binoculaire altérée/absente, fréquente en cas de strabisme<br>\n              <em>Présence d’une vision stéréoscopique fine</em> = élément pronostique favorable\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Si disparition complète du strabisme avec correction optique</strong></td>\n            <td><span class=\"kw-def\">Strabisme accommodatif</span> → port de la correction + <span class=\"kw-def\">surveillance</span> seuls.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Axe 4 — Recherche d’une cause organique (LAF + <span class=\"kw-imagerie\">FO</span>) ⭐</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Recherche</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Segment antérieur</strong> (lampe à fente)</td>\n            <td>\n              Perte de transparence des milieux : <span class=\"kw-alerte\">opacité cornéenne</span>, <span class=\"kw-alerte\">cataracte</span><br>\n              Anomalies iridiennes, séquelles de <span class=\"kw-ttt\">chirurgie</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fond d’œil</strong></td>\n            <td>\n              <span class=\"kw-etio\">Rétinoblastome</span><br>\n              Cicatrice maculaire<br>\n              Neuropathie optique\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\" style=\"background:#f3dccf;border-left:4px solid var(--danger);\">\n        <strong>⚠️ Pas de test de Lancaster chez l’enfant strabique.</strong> Le cerveau neutralise l’image pathologique → pas de diplopie → test inapplicable. Le test de Lancaster reste réservé à l’adulte avec diplopie binoculaire (paralysie oculomotrice <span class=\"kw-etio\">acquise</span>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> nourrisson, enfant, adolescent</em></p>","frequence":1},{"id":"52-4","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales causes d’amblyopie","contenu":"<p>L’<span class=\"kw-def\">amblyopie</span> est une acuité visuelle effective inférieure à l’acuité optimale théorique. Au sens strict, elle désigne <span class=\"kw-clinique\">les</span> amblyopies <strong>fonctionnelles</strong>, classées en <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>randes catégories selon leur mécanisme. Au sens large, elle englobe aussi les amblyopies organiques.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Repères épidémiologiques</h4>\n      <ul>\n        <li><span class=\"kw-def\">Prévalence</span> : <span class=\"kw-chiffre\">2-5 %</span> des enfants (collège de pédiatrie).</li>\n        <li>Risque : <span class=\"kw-alerte\">trouble irréversible</span> de la maturation du cortex visuel si non traité avant la fin de la période sensible.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Amblyopies organiques (sens large)</h4>\n      <p>Résultent d’une <strong>malformation ou <span class=\"kw-clinique\">lésion</span></strong> de l’œil ou des voies visuelles responsable d’une mauvaise vision : rétinoblastome, cicatrice maculaire, neuropathie optique, malformation chorio-rétinienne, anomalies des voies visuelles.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Amblyopies fonctionnelles — 3 types ⭐</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Mécanisme et étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Amblyopie de privation</span></strong></td>\n            <td>\n              <strong>Cause :</strong> privation par la rétine de l’image qui devrait s’y former<br>\n              <strong>Étiologies :</strong>\n              <ul>\n                <li><span class=\"kw-alerte\">Ptosis congénital complet</span></li>\n                <li><span class=\"kw-alerte\">Hémangiome infantile de la paupière supérieure</span></li>\n                <li><span class=\"kw-etio\">Cataracte congénitale</span></li>\n              </ul>\n              <strong>CAT :</strong> PEC <em>très rapide</em>, dès <span class=\"kw-clinique\">les</span> 1ʳᵉˢ semaines/mois de vie si cause <span class=\"kw-etio\">congénitale</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Amblyopie strabique</span></strong></td>\n            <td>\n              <strong>Cause :</strong> déviation de l’image provenant de l’œil dévié → neutralisation corticale → arrêt du développement de l’œil non fixateur<br>\n              <strong>Si strabisme alternant</strong> : il n’existe <em>pas</em> d’amblyopie (AV équivalente aux 2 yeux)<br>\n              <strong>Si fixation préférentielle d’un seul œil</strong> : risque majeur<br>\n              <span class=\"kw-alerte\">Considérées comme définitives au-delà de 8-10 ans</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Amblyopie réfractive</span></strong></td>\n            <td>\n              <strong>Cause :</strong> flou de l’image provenant d’un œil <em>myope, hypermétrope ou ast<span class=\"kw-chiffre\">igm</span>ate</em> non corrigé<br>\n              Souvent <span class=\"kw-clinique\">anisométropique</span> (amétropie non symétrique entre <span class=\"kw-clinique\">les</span> 2 yeux)<br>\n              Certaines amblyopies anisométropiques <em>modérées</em> peuvent encore être traitées plus tardivement\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Délais critiques de prise en charge ⭐</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Les</span> amblyopies fonctionnelles sont <strong>réversibles</strong> si la cause est traitée précocement, <span class=\"kw-alerte\">irréversibles si PEC trop tardive</span>.</li>\n        <li>Rééducation <strong>avant <span class=\"kw-chiffre\">6 ans</span></strong> → souvent une récupération visuelle optimale.</li>\n        <li><span class=\"kw-alerte\">Après 6 ans → récupération très limitée voire impossible.</span></li>\n        <li>Plus le traitement est précoce, plus il est rapide et efficace ; sinon il sera plus long et moins efficace.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Principes de PEC.</strong>\n        <ol>\n          <li><span class=\"kw-def\">Dépistage</span> puis traitement d’une éventuelle <span class=\"kw-alerte\">pathologie organique</span> (cataracte, rétinoblastome…).</li>\n          <li><strong>Occlusion de l’œil dominant/sain</strong> par patch collé sur la peau + <strong>port de la <span class=\"kw-ttt\">correction optique totale</span></strong> — jusqu’à <span class=\"kw-chiffre\">8-10 ans</span>.</li>\n          <li>Méthodes optiques ou pharmacologiques (= <em>pénalisation</em> de l’œil dominant) peuvent prendre le relais.</li>\n        </ol>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 297 — Cancer de l’enfant (rétinoblastome) · 55 — Développement psychomoteur</em></p>","frequence":0},{"id":"52-5","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales causes de strabisme de l’enfant","contenu":"<p>Trois grands types de strabisme à distinguer — la <span class=\"kw-def\">classification</span> est <em>physiopathologique</em>, fondée sur le mécanisme dominant (moteur, sensoriel, ou « maladie »).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Classification</span> physiopathologique ⭐</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Strabisme paralytique</th><th>Strabisme sensoriel</th><th>Strabisme-maladie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Physiopath.</strong></td>\n            <td>Dysfonction <strong>motrice</strong></td>\n            <td>Dysfonction <strong>sensorielle</strong></td>\n            <td>Part des mécanismes sensoriels/moteurs <em>discutée</em></td>\n          </tr>\n          <tr>\n            <td><strong>Exemple</strong></td>\n            <td>Tumeur → <span class=\"kw-alerte\">HTIC</span> → paralysie du <strong>VI</strong> → strabisme convergent</td>\n            <td>Rétinoblastome affectant la macula → malvoyance unilatérale → strabisme sensoriel</td>\n            <td>Strabismes précoces, accommodatifs, aigus normosensoriels…</td>\n          </tr>\n          <tr>\n            <td><strong>Étiologies à dépister</strong></td>\n            <td>Grand nombre de <span class=\"kw-etio\">tumeurs cérébrales</span> de l’enfant se manifestent par un strabisme</td>\n            <td>Grand nombre de <span class=\"kw-etio\">maladies de l’œil</span> de l’enfant (cataractes, rétinopathies, rétinoblastome) se manifestent par un strabisme</td>\n            <td>Diagnostic <em>d’élimination</em> (après bilan exhaustif normal)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Causes paralytiques (strabismes incomitants) ⭐</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Tumeurs cérébrales</span> de l’enfant — <span class=\"kw-alerte\">HTIC</span> → paralysie oculomotrice (VI ++).</li>\n        <li>Atteintes des nerfs crâniens III, IV, VI (post-infectieuses, traumatiques, malformatives, vasculaires).</li>\n        <li>Syndromes congénitaux à expression oculomotrice (Duane, Brown).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Causes sensorielles (<span class=\"kw-clinique\">lésion</span> oculaire/visuelle initiale) ⭐</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Cataracte congénitale</span> — opacification du cristallin altérant le développement visuel.</li>\n        <li><span class=\"kw-etio\">Rétinoblastome</span> — tumeur maligne, leucocorie associée fréquente.</li>\n        <li>Autres rétinopathies de l’enfant (rétinopathie du prématuré, dystrophies rétiniennes…).</li>\n        <li>Toute pathologie générant une <em>malvoyance unilatérale</em>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Causes « maladie » (strabismes concomitants) ⭐</h4>\n      <ul>\n        <li><strong>Strabismes accommodatifs</strong> — sur <span class=\"kw-etio\">hypermétropie non corrigée</span>, déclenchement par excès d’accommodation et syncinésie accommodation-convergence-myosis. Disparition complète avec correction optique = strabisme accommodatif pur.</li>\n        <li><strong>Strabismes précoces</strong> (&lt;<span class=\"kw-chiffre\"> 6 mois</span>) — souvent <span class=\"kw-etio\">exotropie</span> précoce associée à des anomalies cérébrales ; absence définitive de vision stéréoscopique fine.</li>\n        <li><strong>Strabismes aigus normosensoriels</strong>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Facteurs de risque</span> à connaître.</strong>\n        <ul>\n          <li><strong>Prématurité</strong> — risque de strabisme précoce ↑.</li>\n          <li><strong>ATCD familiaux</strong> de strabisme ou d’amblyopie — risque de strabisme accommodatif ↑.</li>\n          <li><strong>Amétropie</strong> non corrigée — hypermétropie ++ (syncinésie accommodation-convergence).</li>\n          <li><strong>Pathologie cérébrale</strong> — préfigure l’exotropie précoce.</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\" style=\"background:#f3dccf;border-left:4px solid var(--danger);\">\n        <strong>🚩 <span class=\"kw-alerte\">Drapeaux rouges</span> — exploration urgente.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Leucocorie</span> associée → rétinoblastome jusqu’à preuve du contraire.</li>\n          <li><span class=\"kw-etio\">Exotropie précoce</span> (&lt;<span class=\"kw-chiffre\"> 9 mois</span>) → anomalies cérébrales à rechercher.</li>\n          <li><span class=\"kw-alerte\">Strabisme incomitant</span> (incomitance directionnelle de l’angle) → paralysie oculomotrice → <span class=\"kw-imagerie\">imagerie cérébrale</span>.</li>\n          <li><strong>Strabisme aigu</strong> avec diplopie chez un enfant plus grand → exploration neurologique.</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 297 — Cancer de l’enfant (rétinoblastome · tumeurs cérébrales) · 105 — Épilepsies de l’enfant et de l’adulte · 47 — <span class=\"kw-def\">Suivi</span> nourrisson, enfant, adolescent</em></p>","frequence":0},{"id":"52-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître le raisonnement diagnostique face à un strabisme de l’enfant","contenu":"<p>Face à un strabisme persistant <strong>au-delà de <span class=\"kw-chiffre\">3 mois</span></strong>, un raisonnement structuré en 4 temps est nécessaire pour distinguer un <em>strabisme-maladie</em> fonctionnel d’un <em>strabisme-symptôme</em> d’une pathologie organique grave.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étape 1 — Caractérisation du strabisme à l’interrogatoire</h4>\n      <table >\n        <thead><tr><th>Caractère</th><th>Pertinence diagnostique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>FR</strong></td>\n            <td>\n              <strong>Prématurité</strong> (risque de strabisme précoce ↑)<br>\n              <strong>ATCD familiaux</strong> de strabisme ou d’amblyopie (risque de strabisme accommodatif ↑)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Date d’apparition</strong></td>\n            <td>Plus elle est précoce, <strong>moins le développement d’une vision binoculaire normale est probable</strong> → <span class=\"kw-ci\">jamais de</span> vision stéréoscopique fine dans le strabisme précoce (&lt; <span class=\"kw-chiffre\">6-9 mois</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Sens de la déviation</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Ésotropie</span> (convergent) : parfois confondu avec <strong>épicanthus</strong> (repli cutané), ou avec une <strong>syncinésie accommodation-convergence</strong> normale en VP<br>\n              <span class=\"kw-alerte\">Exotropie</span> (divergent) : si précoce (&lt;<span class=\"kw-chiffre\"> 9 mois</span>) → <strong>anomalies cérébrales</strong> à évoquer<br>\n              <span class=\"kw-clinique\">Hypertropie / Hypotropie</span> : strabisme vertical\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Intermittent <span class=\"kw-bio\">vs</span> Permanent</strong></td>\n            <td><span class=\"kw-alerte\">Pas de vision binoculaire</span> en cas de strabisme permanent → amblyopie strabique probable.</td>\n          </tr>\n          <tr>\n            <td><strong>Dominance / Alternance</strong></td>\n            <td>\n              <strong>Fixation alternée</strong> : risque d’amblyopie <em>modéré</em><br>\n              <strong>Œil dévié toujours le même</strong> : risque d’amblyopie <span class=\"kw-alerte\">majeur</span> — l’œil non fixateur devient amblyope\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étape 2 — Examens diagnostiques ⭐</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Intérêt diagnostique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Étude des reflets cornéens</strong></td>\n            <td><span class=\"kw-def\">Diagnostic positif</span> : reflet dévié pour l’œil strabique.</td>\n          </tr>\n          <tr>\n            <td><strong>Test à l’écran unilatéral alterné</strong></td>\n            <td>Mouvement de <strong>refixation</strong> de l’œil strabique = strabisme confirmé.</td>\n          </tr>\n          <tr>\n            <td><strong>Test de motilité oculaire</strong> (ductions / versions)</td>\n            <td>Rechercher une <span class=\"kw-alerte\">paralysie oculomotrice</span> = strabismes <em>incomitants</em>.</td>\n          </tr>\n          <tr>\n            <td><strong>Réfraction sous cycloplégie</strong> (skiascopie)</td>\n            <td>Dépister une <span class=\"kw-etio\">hypermétropie latente</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Examen du segment antérieur</strong> (lampe à fente)</td>\n            <td>Dépister une <span class=\"kw-alerte\">cataracte</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Examen du segment postérieur</strong> (fond d’œil)</td>\n            <td>Dépister un <span class=\"kw-alerte\">rétinoblastome</span> ou autre pathologie rétinienne.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étape 3 — Examens à visée pronostique</h4>\n      <ul>\n        <li><strong>Mesure de la vision binoculaire</strong> (stéréotests : Lang, Randot, Wirt, TNO) → indicateur pronostique.</li>\n        <li><strong>Mesure de l’angle de déviation</strong> (examen sous écran + prismes) → indication chirurgicale si angle résiduel persistant malgré la correction optique optimale.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étape 4 — Stratégie selon la réponse à la correction optique</h4>\n      <table >\n        <thead><tr><th>Réponse</th><th>Conclusion</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Disparition complète</strong> du strabisme avec la correction optique</td>\n            <td><span class=\"kw-def\">Strabisme accommodatif</span> → aucun autre traitement que le port de la correction optique + <span class=\"kw-def\">surveillance</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Angle de déviation résiduel</strong></td>\n            <td>Étude des reflets ou test de Brückner pour visualiser la déviation → orientation vers indication chirurgicale.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\" style=\"background:#f3dccf;border-left:4px solid var(--danger);\">\n        <strong>⚠️ Pas de test de Lancaster chez l’enfant.</strong> Le cerveau de l’enfant <strong>neutralise</strong> l’image pathologique → il n’a pas de diplopie → le test de Lancaster (qui repose sur la diplopie) <span class=\"kw-alerte\">n’est pas applicable</span> dans le strabisme de l’enfant.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étape 5 — Arbre d’orientation étiologique (cause fonctionnelle <span class=\"kw-bio\">vs</span> organique) ⭐⭐</h4>\n      <p>📌 Deux principales étiologies à dépister face à un strabisme pathologique persistant :</p>\n      <ul>\n        <li><strong>Cause fonctionnelle</strong> :\n          <ul>\n            <li><span class=\"kw-etio\">Hypermétropie</span> → déviation oculaire compensatrice (strabisme accommodatif).</li>\n            <li><span class=\"kw-def\">Dépistage</span> d’une <strong>amblyopie</strong> associée (mesure de l’AV adaptée à l’âge).</li>\n          </ul>\n        </li>\n        <li><strong>Cause organique avec leucocorie</strong> (réflexe pupillaire blanchâtre) :\n          <ul>\n            <li><span class=\"kw-etio\">Rétinoblastome</span> — tumeur maligne rare, <span class=\"kw-alerte\">urgence</span> diagnostique.</li>\n            <li><span class=\"kw-etio\">Cataracte congénitale</span> — opacification du cristallin altérant le développement visuel.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Conclusion.</strong> Un strabisme persistant chez l’enfant doit être <em>exploré précocement</em> pour éviter <span class=\"kw-clinique\">les</span> complications visuelles (amblyopie) <strong>et</strong> pour identifier une éventuelle cause organique grave (rétinoblastome, cataracte <span class=\"kw-etio\">congénitale</span>). La présence d’une <span class=\"kw-alerte\">leucocorie</span> impose une consultation ophtalmologique en <em><span class=\"kw-alerte\">urgence</span> absolue</em>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 297 — Cancer de l’enfant · 47 — <span class=\"kw-def\">Suivi</span> nourrisson, enfant, adolescent</em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> tout strabisme est considéré comme une <span class=\"kw-alerte\">urgence</span>.<br><strong>Délai :</strong> consultation ophtalmologique dans un délai de <span class=\"kw-chiffre\">1 semaine</span>.<br><strong>Amblyopie :</strong> PEC avant <span class=\"kw-chiffre\">2 ans</span> → succès dans <span class=\"kw-chiffre\">&gt; 90 %</span> des cas ; récupération <span class=\"kw-alerte\">très faible après 8 ans</span>.<br><strong>Privation <span class=\"kw-etio\">congénitale</span> :</strong> <span class=\"kw-etio\">cataracte congénitale</span>, <span class=\"kw-etio\">ptosis congénital complet</span>, <span class=\"kw-etio\">hémangiome de la paupière supérieure</span> → PEC <span class=\"kw-alerte\">dès les 1ères semaines / mois de vie</span>.<br><strong>1er geste :</strong> étude des <span class=\"kw-clinique\">reflets cornéens</span> et <span class=\"kw-clinique\">test à l'écran</span> pour confirmer la déviation.</p>","hospit":"<p><strong>Ambulatoire :</strong> PEC coordonnée par l'<span class=\"kw-ttt\">ophtalmologiste</span> conjointement avec l'<span class=\"kw-ttt\">orthoptiste</span> (mesure des déviations, <span class=\"kw-def\">suivi</span> de l'amblyopie).<br><strong><span class=\"kw-ttt\">Chirurgie</span> :</strong> sous <span class=\"kw-ttt\">anesthésie générale</span>, en <span class=\"kw-alerte\">hospitalisation</span> <span class=\"kw-ttt\">ambulatoire</span>, en <span class=\"kw-chiffre\">fin de maternelle</span>.<br><strong>Alerte :</strong> suspicion de <span class=\"kw-etio\">cause organique</span> (rétinoblastome, cataracte) ou de strabisme <span class=\"kw-etio\">paralytique</span> (tumeur cérébrale) → orientation spécialisée <span class=\"kw-alerte\">urgente</span>.</p>","redflags":"<ul><li>Strabisme <span class=\"kw-alerte\">constant</span> (toujours pathologique)</li><li>Strabisme <span class=\"kw-alerte\">divergent / exotropie</span> (toujours pathologique)</li><li>Strabisme persistant <span class=\"kw-alerte\">après 3 mois</span></li><li>Exotropie <span class=\"kw-chiffre\">précoce (&lt; 9 mois)</span> → souvent associée à des <span class=\"kw-alerte\">anomalies cérébrales</span></li><li><span class=\"kw-clinique\">Leucocorie</span> (reflet pupillaire blanchâtre) → <span class=\"kw-etio\">rétinoblastome</span>, <span class=\"kw-etio\">cataracte congénitale</span></li><li>Strabisme <span class=\"kw-alerte\">incomitant</span> / paralysie oculomotrice → <span class=\"kw-etio\">tumeur cérébrale</span> (<span class=\"kw-alerte\">HTIC</span>, paralysie du VI)</li><li>Œil constamment dévié (non alternant) → <span class=\"kw-alerte\">amblyopie strabique</span> de l'œil non fixateur</li><li>Différence d'acuité visuelle <span class=\"kw-chiffre\">≥ 2/10e</span> entre <span class=\"kw-clinique\">les</span> 2 yeux → suspicion d'<span class=\"kw-etio\">amblyopie</span></li></ul>","principes":"<p>Face à un strabisme non paralytique, la <span class=\"kw-ttt\">1ère étape</span> est le <span class=\"kw-def\">dépistage</span> puis le traitement d'une éventuelle <span class=\"kw-etio\">pathologie organique</span> ; tout patient strabique et/ou amblyope doit porter la <span class=\"kw-ttt\">correction optique totale</span>.</p><p><strong>1 — Éliminer / traiter une cause organique</strong></p><p>Étape préalable indispensable avant tout traitement du strabisme.</p><ul><li><span class=\"kw-def\">Dépistage</span> et traitement d'une <span class=\"kw-etio\">cataracte</span> ou d'un <span class=\"kw-etio\">rétinoblastome</span> en priorité</li><li><span class=\"kw-etio\">Amblyopie de privation</span> <span class=\"kw-etio\">congénitale</span> → PEC <span class=\"kw-alerte\">dès les 1ères semaines / mois de vie</span></li></ul><p><strong>2 — Correction optique totale</strong></p><p>Indiquée chez tout patient strabique et/ou amblyope.</p><ul><li><span class=\"kw-ttt\">Correction optique totale</span> après <span class=\"kw-ttt\">réfraction objective sous cycloplégique</span> (<span class=\"kw-ttt\">atropine</span> / <span class=\"kw-ttt\">cyclopentolate</span>)</li><li>Disparition complète sous correction → <span class=\"kw-etio\">strabisme accommodatif</span> : <span class=\"kw-ttt\">correction optique</span> + <span class=\"kw-def\">surveillance</span>, aucun autre traitement</li></ul><p><strong>3 — Traitement de l'amblyopie</strong></p><p>Réversible <span class=\"kw-chiffre\">avant 6 ans</span>, <span class=\"kw-alerte\">définitive au-delà de 8-10 ans</span>.</p><ul><li><span class=\"kw-ttt\">Occlusion</span> de l'œil dominant / sain par patch collé + port de la correction optique</li><li>Entretenu jusqu'à l'âge de <span class=\"kw-chiffre\">8-10 ans</span></li><li><span class=\"kw-ttt\">Pénalisation</span> optique ou pharmacologique de l'œil dominant en relais</li><li>But : l'<span class=\"kw-def\">iso-acuité</span></li></ul><p><strong>4 — Traitement chirurgical</strong></p><p>Bénéfice fonctionnel et esthético-social ; risque de <span class=\"kw-alerte\">perforation du globe</span> (exceptionnel).</p><ul><li>Indiqué si <span class=\"kw-clinique\">angle de déviation résiduel</span> malgré la correction optique totale</li><li>Réalisé après traitement de l'amblyopie, en <span class=\"kw-chiffre\">fin de maternelle</span></li><li>Affaiblir ou renforcer <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">muscles oculomoteurs</span>, sous <span class=\"kw-ttt\">anesthésie générale</span></li><li><span class=\"kw-ttt\">Toxine botulique</span> (Botox) chez le nourrisson pour <span class=\"kw-clinique\">les</span> strabismes précoces</li></ul>","suivi":"<p><strong>Rythme :</strong> <span class=\"kw-def\">suivi</span> conjoint <span class=\"kw-ttt\">ophtalmologiste</span> / <span class=\"kw-ttt\">orthoptiste</span> ; traitement de l'amblyopie entretenu jusqu'à <span class=\"kw-chiffre\">8-10 ans</span>.<br><strong>Acuité visuelle :</strong> surveiller la <span class=\"kw-clinique\">différence d'AV entre les 2 yeux</span> (<span class=\"kw-chiffre\">≥ 2/10e</span> → reprise du traitement).<br><strong><span class=\"kw-def\">Pronostic</span> :</strong> mesure de la <span class=\"kw-def\">vision binoculaire</span> (<span class=\"kw-ttt\">stéréotest de Lang</span>, Randot) = indicateur pronostique ; <span class=\"kw-clinique\">angle de déviation</span> résiduel = indication chirurgicale.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Strabisme de l'enfant — Caractériser : date d'apparition, constance, sens de la déviation, alternance","detail":"<h4>CAT — Strabisme de l'enfant — Orientation diagnostique et thérapeutique devant un strabisme</h4>","branches":[{"to":"t-physio","label":"Intermittent + alternant + convergent, < 3 mois","color":"green"},{"to":"q-etio","label":"Constant / divergent / après > 3 mois → pathologique (urgence ≤ 1 sem)","color":"red"}]},{"id":"t-physio","kind":"terminal","label":"<span class=\"kw-def\">Surveillance</span> — strabisme possiblement non pathologique — < <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> mois</span>, intermittent et alternant","color":"green","detail":"<h4>Conduite</h4><ul><li>Simple <span class=\"kw-def\">retard d'acquisition de l'oculomotricité</span> avec spasmes accommodatifs</li><li><span class=\"kw-clinique\">Surveillance</span> ophtalmologique et <span class=\"kw-def\">réévaluation</span></li></ul><h4>Délai</h4><ul><li>Devient <span class=\"kw-alerte\">pathologique</span> si le strabisme persiste <span class=\"kw-chiffre\">après 3 mois</span></li></ul>"},{"id":"q-etio","kind":"decision","label":"Bilan ophtalmologique étiologique — Motilité oculaire · fond d'œil · segment antérieur · réfraction sous cycloplégique","branches":[{"to":"t-paralytique","label":"Strabisme incomitant / paralysie oculomotrice","color":"red"},{"to":"t-organique","label":"Leucocorie / cause organique","color":"red"},{"to":"q-accom","label":"Hypermétropie, examen organique normal","color":"amber"}]},{"id":"t-paralytique","kind":"terminal","label":"Strabisme paralytique — recherche d'une cause neurologique — Strabisme incomitant","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Limitation de l'abduction</span> (ex. paralysie du <span class=\"kw-etio\">VI</span>)</li><li>Angle entre <span class=\"kw-clinique\">les</span> 2 yeux <span class=\"kw-clinique\">variable selon la direction du regard</span> (incomitance)</li></ul><h4>Conduite</h4><ul><li>Rechercher une <span class=\"kw-etio\">tumeur cérébrale</span> de l'enfant (<span class=\"kw-alerte\">HTIC</span>)</li></ul>"},{"id":"t-organique","kind":"terminal","label":"Cause organique — urgence diagnostique — Leucocorie / anomalie du globe","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Leucocorie</span> (reflet pupillaire blanchâtre)</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Rétinoblastome</span> (tumeur maligne)</li><li><span class=\"kw-etio\">Cataracte congénitale</span></li></ul><h4>Traitement</h4><ul><li>Traitement de la <span class=\"kw-etio\">pathologie organique</span> en priorité</li><li><span class=\"kw-etio\">Amblyopie de privation</span> → PEC <span class=\"kw-alerte\">dès les 1ères semaines / mois de vie</span></li></ul>"},{"id":"q-accom","kind":"decision","label":"Disparition complète sous correction optique totale ?","branches":[{"to":"t-accom","label":"Oui — disparition complète","color":"green"},{"to":"t-amblyopie","label":"Non — angle résiduel","color":"amber"}]},{"id":"t-accom","kind":"terminal","label":"Strabisme accommodatif — correction optique seule — Disparition complète sous correction","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Correction optique totale</span> (après réfraction sous cycloplégique)</li><li>Aucun autre traitement nécessaire</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-clinique\">Surveillance</span> simple</li></ul>"},{"id":"t-amblyopie","kind":"terminal","label":"Angle résiduel ± amblyopie — traitement spécialisé — Pas de disparition sous correction","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Correction optique totale</span> systématique</li><li>Si amblyopie : <span class=\"kw-ttt\">occlusion</span> de l'œil sain par patch jusqu'à <span class=\"kw-chiffre\">8-10 ans</span> ± <span class=\"kw-ttt\">pénalisation</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Chirurgie</span> si <span class=\"kw-clinique\">angle résiduel</span> malgré correction, après traitement de l'amblyopie (<span class=\"kw-chiffre\">fin de maternelle</span>)</li></ul><h4>Délai</h4><ul><li>Amblyopie réversible <span class=\"kw-chiffre\">avant 6 ans</span>, <span class=\"kw-alerte\">définitive après 8-10 ans</span></li></ul>"}]},"cards":[{"i":"63915b70f48d","n":52,"o":"52-2","u":"Diagnostic positif","t":"Connaître les modalités de dépistage d’un strabisme et d’un risque d’amblyopie chez l’enfant","q":"Comment définir le strabisme chez l'enfant ?","a":"<p>C'est un trouble oculomoteur caractérisé par une <strong>déviation des axes visuels</strong>. Il comporte toujours une composante motrice et une composante sensorielle.</p>"},{"i":"669f22add959","n":52,"o":"52-2","u":"Diagnostic positif","t":"Connaître les modalités de dépistage d’un strabisme et d’un risque d’amblyopie chez l’enfant","q":"Quels tests sont utilisés pour le dépistage de l'acuité visuelle chez l'enfant d'âge verbal, et quel est le critère majeur de suspicion d'amblyopie ?","a":"<ul><li>Entre 2,5 et 4 ans : tests de <strong>Piga ssou</strong> ou du <strong>Cadet</strong>.</li><li>À partir de 5 ans : tests du <strong>Cadet</strong> ou échelle de <strong>Monoyer</strong>.</li></ul><p>Le critère majeur de suspicion d'amblyopie n'est pas le score brut, mais une <strong>différence d'acuité visuelle ≥ 2/10<sup>e</sup> entre les deux yeux</strong>.</p>"},{"i":"ac8fd1755b14","n":52,"o":"52-2","u":"Diagnostic positif","t":"Connaître les modalités de dépistage d’un strabisme et d’un risque d’amblyopie chez l’enfant","q":"Comment définir l'amblyopie fonctionnelle chez l'enfant ?","a":"<p>L'amblyopie fonctionnelle est une <strong>acuité visuelle</strong> effective d'un œil inférieure à l'acuité visuelle optimale théorique, caractérisée par une <strong>différence ≥ 2/10<sup>e</sup></strong> entre les deux yeux avec correction.</p>"},{"i":"bc16f2ca8c6a","n":52,"o":"52-2","u":"Diagnostic positif","t":"Connaître les modalités de dépistage d’un strabisme et d’un risque d’amblyopie chez l’enfant","q":"Quels sont les méthodes de dépistage de l'amblyopie chez l'enfant d'âge pré-verbal ?","a":"<ul><li>L'évaluation comportementale : <strong>poursuite-fixation</strong>, sourires-réponses, <strong>défense à l'occlusion</strong>, harmonie marche/jeu.</li><li>Le <strong>test d'occlusion</strong> : recherche d'une réaction de défense lors de l'occlusion de l'œil sain.</li><li>Le <strong>test stéréoscopique (Lang)</strong> : entre 9 et 15 mois.</li></ul>"},{"i":"bdf402e12433","n":52,"o":"52-2","u":"Diagnostic positif","t":"Connaître les modalités de dépistage d’un strabisme et d’un risque d’amblyopie chez l’enfant","q":"Quand un strabisme est-il considéré comme pathologique chez l'enfant, justifiant une consultation ophtalmologique ?","a":"<ul><li>Un strabisme <strong>constant</strong>, quel que soit l'âge.</li><li>Un strabisme <strong>divergent (exotropie)</strong>, qui, s'il est précoce (< 9 mois), est souvent associé à des anomalies cérébrales.</li><li>Tout strabisme persistant <strong>après 3 mois</strong>.</li></ul>"},{"i":"d6b549acc588","n":52,"o":"52-2","u":"Diagnostic positif","t":"Connaître les modalités de dépistage d’un strabisme et d’un risque d’amblyopie chez l’enfant","q":"Quels sont les facteurs de risque d'amétropie qui exposent à un risque fort de strabisme ou d'amblyopie chez l'enfant ?","a":"<p>Il s'agit d'une <strong>hypermétropie > 3,5 D</strong>, d'un <strong>astigmatisme > 1,5 D</strong>, ou d'une <strong>anisométropie > 1 D</strong>.</p>"},{"i":"de2ce2c664ab","n":52,"o":"52-2","u":"Diagnostic positif","t":"Connaître les modalités de dépistage d’un strabisme et d’un risque d’amblyopie chez l’enfant","q":"Comment dépister un strabisme au cabinet médical chez l'enfant ?","a":"<ul><li>L'étude des <strong>reflets cornéens</strong> : le reflet est dévié pour l'œil strabique par rapport à l'œil fixateur.</li><li>Le <strong>test à l'écran unilatéral alterné</strong> : il recherche un mouvement de refixation de l'œil strabique lors de la levée d'occlusion.</li><li>La <strong>réfraction objective sous cycloplégique</strong> (entre 9 et 12 mois) : mesure de l'amétropie (myopie, hypermétropie, astigmatisme) avec fond d'œil associé.</li></ul>"}]};